// remember that type_info is implementation dependent
std::ostream& printType(std::ostream &os, const char *s)
{
	// exit condition
	if (!s)
		return os;
	// skip non-alphabetic characters
	while (!isalpha(*s))
		++s;
	// pointer
	if (*s == 'P') {
		os << "pointer to ";
		return printType(os, ++s);
	}
	// built-in types (not all types)
	if (*s == 'c')
		return os << "char";
	if (*s == 'd')
		return os << "double";
	if (*s == 'f')
		return os << "float";
	if (*s == 'i')
		return os << "int";
	if (*s == 'j')
		return os << "unsigned";
	// array
	if (*s == 'A') {
		os << "array of ";
		for (++s; isdigit(*s); ++s) {
			os << *s;
		}
		os << ' ';
		return printType(os, s);
	}
	// library string
	if (!strcmp(s, "NSt7__cxx1112basic_stringIcSt11char_traitsIcESaIcEEE"))
		return os << "string";
	return os << s;  // user defined types
}

