					std::shared_ptr<std::vector<std::string>> f) :
			        sought(s), lines(p), file(f) {}
		auto begin() const { return lines->begin(); }
		auto end() const { return lines->end(); }
		std::shared_ptr<std::vector<std::string>>
			get_file() const { return file; }
